"""The engage/restore discipline, proven on fakes (FILTER-SPEC's
Windows-edition rules, carried to Debian): root first; proof before
pointing, per family; save verified before change, never
overwritten; a loopback can never be an original; every change
verified by read-back and a live question; restore exact, verified,
and only then is the record retired; leftovers and unknowns are
their own states, never silently handled."""
import base64
import hashlib
import json

import pytest

from conftest import FakeProofer, FakeView, GarblingView, stub_resolved_view
from sphinx_deb.resolver.guard import (
    BackupRecord,
    DnsGuard,
    DnsState,
    RightsRequiredError,
    Stack,
    detect_stack,
)
from sphinx_deb.resolver.systemview import nameservers_in

ORIGINAL = b"# my resolver\nsearch home.lan\nnameserver 192.168.1.1\noptions ndots:2\n"


def _guard(view, tmp_path):
    return DnsGuard(view, tmp_path)


# --- stack detection --------------------------------------------------


def test_detect_direct_stack():
    assert detect_stack(FakeView()) == Stack.DIRECT


def test_detect_resolved_stub_stack():
    assert detect_stack(stub_resolved_view()) == Stack.RESOLVED


def test_detect_networkmanager_refuses_the_guard_later():
    assert detect_stack(FakeView(nm_manages=True)) == Stack.NETWORKMANAGER


def test_detect_other_stacks():
    assert detect_stack(FakeView(symlink="/run/resolvconf/resolv.conf")) == Stack.OTHER
    assert detect_stack(FakeView(resolv=b"# Generated by dhcpcd\nnameserver 1.1.1.1\n")) == Stack.OTHER
    assert detect_stack(FakeView(resolv=b"")) == Stack.OTHER
    # resolved installed but not in stub mode: not Phase 1's to take.
    assert (
        detect_stack(
            FakeView(
                symlink="../run/systemd/resolve/resolv.conf",
                resolved_active=True,
                resolv=b"nameserver 192.168.1.1\n",
            )
        )
        == Stack.OTHER
    )


# --- direct stack: the happy round trip --------------------------------


def test_engage_then_restore_is_byte_exact(tmp_path):
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer())
    assert result.ok
    engaged = view.resolv
    assert nameservers_in(engaged) == ["127.0.0.1", "::1"]
    # The machine's own non-nameserver lines ride along.
    assert b"search home.lan" in engaged
    assert b"options ndots:2" in engaged
    assert guard.detect_state() == DnsState.ENGAGED
    assert guard.load_intent()["engaged"] is True

    restored = guard.disengage()
    assert restored.ok
    assert view.resolv == ORIGINAL  # byte-for-byte
    assert not guard.backup_file.exists()
    assert guard.detect_state() == DnsState.DISENGAGED
    assert guard.load_intent()["engaged"] is False


def test_engage_records_the_original_verifiably(tmp_path):
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    assert guard.engage(FakeProofer()).ok
    record = guard.load_backup()
    assert record is not None
    assert record.original_resolv_conf() == ORIGINAL


# --- the toll: proof before pointing ------------------------------------


def test_no_proof_no_pointing_and_no_record(tmp_path):
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer(answers={}))
    assert not result.ok
    assert "not answering" in result.message
    assert view.resolv == ORIGINAL
    assert not guard.backup_file.exists()
    assert guard.load_intent() is None  # intent only at real transitions


def test_partial_family_engagement_is_reported_as_partial(tmp_path):
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer(answers={"127.0.0.1": True}))
    assert result.ok
    assert result.engaged_loopbacks == ["127.0.0.1"]
    assert nameservers_in(view.resolv) == ["127.0.0.1"]
    assert "IPv6" in result.message and "left unchanged" in result.message
    assert guard.disengage().ok
    assert view.resolv == ORIGINAL


def test_root_is_required_before_anything_is_touched(tmp_path):
    view = FakeView(root=False, resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    with pytest.raises(RightsRequiredError):
        guard.engage(FakeProofer())
    with pytest.raises(RightsRequiredError):
        guard.disengage()
    assert view.resolv == ORIGINAL
    assert view.calls == []


# --- a loopback can never become an original -----------------------------


def test_fresh_engage_refuses_a_loopback_original(tmp_path):
    view = FakeView(resolv=b"nameserver 127.0.0.1\n")
    guard = _guard(view, tmp_path)
    assert guard.detect_state() == DnsState.UNKNOWN
    result = guard.engage(FakeProofer())
    assert not result.ok
    assert not guard.backup_file.exists()
    assert view.resolv == b"nameserver 127.0.0.1\n"


def test_restore_refuses_when_there_is_nothing_it_saved(tmp_path):
    view = FakeView(resolv=b"nameserver 127.0.0.1\n")
    guard = _guard(view, tmp_path)
    result = guard.disengage()
    assert not result.ok
    assert "no saved record" in result.message


def test_a_pure_loopback_record_is_corrupt_by_construction(tmp_path):
    poisoned = BackupRecord(
        stack="direct",
        engaged_loopbacks=["127.0.0.1"],
        resolv_conf_b64=base64.b64encode(b"nameserver 127.0.0.1\n").decode(),
        resolv_conf_sha256=hashlib.sha256(b"nameserver 127.0.0.1\n").hexdigest(),
    )
    (tmp_path / "dns-backup.json").write_text(json.dumps(poisoned.to_dict()))
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    assert guard.load_backup() is None
    assert guard.backup_problem() is not None
    assert not guard.engage(FakeProofer()).ok
    assert not guard.disengage().ok
    assert guard.backup_file.exists()  # never silently removed


def test_an_unreadable_record_blocks_and_is_kept(tmp_path):
    (tmp_path / "dns-backup.json").write_text("{ this is not json")
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    assert guard.backup_problem() is not None
    assert not guard.engage(FakeProofer()).ok
    assert not guard.disengage().ok
    assert guard.backup_file.exists()


# --- the record is never overwritten --------------------------------------


def test_leftover_reengage_restores_the_first_recorded_original(tmp_path):
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    assert guard.engage(FakeProofer()).ok
    view.resolv = ORIGINAL  # the user put DNS back by hand
    assert guard.detect_state() == DnsState.LEFTOVER
    # Meanwhile the machine's "original" has moved on — a re-engage
    # must NOT record the new values over the saved ones.
    view.resolv = b"nameserver 8.8.8.8\n"
    assert guard.engage(FakeProofer()).ok
    assert guard.disengage().ok
    assert view.resolv == ORIGINAL  # the FIRST originals, exactly


def test_dismiss_leftover_and_never_while_engaged(tmp_path):
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    assert guard.engage(FakeProofer()).ok
    assert not guard.dismiss_leftover().ok  # engaged: restore first
    view.resolv = ORIGINAL
    assert guard.detect_state() == DnsState.LEFTOVER
    assert guard.dismiss_leftover().ok
    assert not guard.backup_file.exists()
    assert view.resolv == ORIGINAL  # dismiss changes no settings


# --- verification and rollback ---------------------------------------------


def test_garbled_writes_are_caught_and_rolled_back(tmp_path):
    view = GarblingView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer())
    assert not result.ok
    assert guard.backup_file.exists()  # kept: it is the only way back
    intent = guard.load_intent()
    assert intent is None or intent["engaged"] is False


def test_engage_when_already_on_is_a_noop_success(tmp_path):
    view = FakeView(resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    assert guard.engage(FakeProofer()).ok
    calls_after_first = len(view.calls)
    result = guard.engage(FakeProofer())
    assert result.ok and "already on" in result.message
    assert len(view.calls) == calls_after_first


# --- the resolved stack ------------------------------------------------------


def test_resolved_engage_and_restore_round_trip(tmp_path):
    view = stub_resolved_view()
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer())
    assert result.ok
    assert view.links["eth0"] == ["127.0.0.1", "::1"]
    # The stub file itself is resolved's: never touched.
    assert view.resolv == b"# stub\nnameserver 127.0.0.53\noptions edns0 trust-ad\n"
    record = guard.load_backup()
    assert record is not None and record.prior_servers == ["192.168.1.1"]
    assert guard.detect_state() == DnsState.ENGAGED

    restored = guard.disengage()
    assert restored.ok
    assert view.links["eth0"] == ["192.168.1.1"]  # revert returned it
    assert not guard.backup_file.exists()


def test_resolved_engage_requires_the_stub_chain_to_answer(tmp_path):
    view = stub_resolved_view()
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer(stub=False))
    assert not result.ok
    assert ("revert", "eth0") in view.calls  # rolled back
    assert view.links["eth0"] == ["192.168.1.1"]
    assert guard.backup_file.exists()  # kept, per the rollback rule


def test_resolved_set_failure_rolls_back(tmp_path):
    view = stub_resolved_view()
    view.fail_set = True
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer())
    assert not result.ok
    assert view.links["eth0"] == ["192.168.1.1"]


def test_resolved_restore_notes_dhcp_renewal_but_is_exact(tmp_path):
    view = stub_resolved_view(revert_to={"eth0": ["10.0.0.1"]})
    guard = _guard(view, tmp_path)
    assert guard.engage(FakeProofer()).ok
    restored = guard.disengage()
    assert restored.ok
    assert "DHCP" in restored.message  # noted, plainly
    assert view.links["eth0"] == ["10.0.0.1"]


def test_resolved_engage_refuses_a_link_with_a_loopback_already(tmp_path):
    view = stub_resolved_view(links={"eth0": ["127.0.0.1", "192.168.1.1"]})
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer())
    assert not result.ok
    assert not guard.backup_file.exists()


def test_resolved_partial_family_points_only_what_was_proven(tmp_path):
    view = stub_resolved_view()
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer(answers={"127.0.0.1": True}))
    assert result.ok
    assert view.links["eth0"] == ["127.0.0.1"]


# --- stacks the guard refuses -----------------------------------------------


def test_networkmanager_machines_are_refused_plainly(tmp_path):
    view = FakeView(nm_manages=True, resolv=ORIGINAL)
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer())
    assert not result.ok
    assert "NetworkManager" in result.message
    assert view.resolv == ORIGINAL
    assert not guard.backup_file.exists()


def test_unrecognized_machines_are_refused_plainly(tmp_path):
    view = FakeView(symlink="/run/resolvconf/resolv.conf", resolv=b"nameserver 1.1.1.1\n")
    guard = _guard(view, tmp_path)
    result = guard.engage(FakeProofer())
    assert not result.ok
    assert view.calls == []
